#include "renderer/SceneRenderer.hpp"
#include "assets/ObjImporter.hpp"
#include <glm/gtc/type_ptr.hpp>
namespace scene_editor {void SceneRenderer::draw(const Scene& scene,const ShaderProgram& shader,const Mesh& cube,const Mesh& sphere,const Mesh& plane){for(const auto& object:scene.objects){if(!object.visible)continue;glm::mat4 model=object.transform.matrix();glUniformMatrix4fv(shader.uniform("model"),1,GL_FALSE,glm::value_ptr(model));if(object.kind==ObjectKind::ImportedModel){auto it=imported_.find(object.geometryPath);if(it==imported_.end()){auto asset=importObj(object.geometryPath);std::vector<Submesh> parts;if(asset.valid())for(auto& src:asset.submeshes){Submesh part;part.material=src.material;part.mesh.upload(src.vertices,src.indices);parts.push_back(std::move(part));}it=imported_.emplace(object.geometryPath,std::move(parts)).first;}for(const auto& part:it->second){materials_.bind(object.materialOverride?object.material:part.material,shader);part.mesh.draw();}}else{materials_.bind(object.material,shader);switch(object.kind){case ObjectKind::Cube:cube.draw();break;case ObjectKind::Sphere:sphere.draw();break;case ObjectKind::Plane:plane.draw();break;case ObjectKind::ImportedModel:break;}}}}}
